import{drawJennSprite}from'./jenn-sprite.mjs';
import{createGame,step,reset,returnToCheckpoint,W,H}from'./engine.mjs';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s),g=createGame(),input={};let playing=false,camera=0,last=0,acc=0,sound=false,audio;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const jennImage=new Image();jennImage.src='assets/jenn-welcome.png';
function tone(freq=520){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),v=audio.createGain();o.type='sine';o.frequency.value=freq;v.gain.setValueAtTime(.035,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+.15);}catch{}}
function clearInput(){for(let k in input)input[k]=false;g.lastJump=false;g.lastDash=false;}
function showMenu(kind){$('#overlay').classList.remove('hidden');let paused=kind==='pause',won=kind==='won';$('#menu-eyebrow').textContent=won?'THE BEST PLACE TO LAND.':paused?'A LITTLE BREATHER.':'WHISKERS UP. ADVENTURE AWAITS.';$('#menu-title').innerHTML=won?'Home, at last.<br><em>Hello, Jenn.</em>':paused?'Take a moment.<br><em>Stretch your paws.</em>':'Small paws.<br><em>Big adventure.</em>';$('#menu-copy').innerHTML=won?`One happy cat. One happy human.<br>${g.collected.size} of 12 yarn balls found along the way.`:paused?'Your cosy checkpoint is right where you left it.':'Help Mew find her way through the garden<br>and back to her favourite person.';$('#start').innerHTML=won?'Play again <span>↻</span>':paused?'Keep exploring <span>→</span>':'Let’s find Jenn <span>→</span>';}
$('#start').onclick=()=>{if(g.won){reset(g);camera=0;}playing=true;g.paused=false;clearInput();$('#overlay').classList.add('hidden');canvas.focus();tone();};
function enterGame(){if(playing)return;$('#title-screen').hidden=true;$('#game-page').hidden=false;$('#start').onclick();}
$('#enter-game').onclick=enterGame;
function pause(){if(!playing||g.won)return;g.paused=!g.paused;clearInput();if(g.paused)showMenu('pause');else{$('#overlay').classList.add('hidden');canvas.focus();}}
$('#pause').onclick=pause;$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';tone();if(playing&&!g.paused&&!g.won)canvas.focus();};
const mapping={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',c:'jump',C:'jump',x:'dash',X:'dash',Shift:'dash'};
window.addEventListener('keydown',e=>{if(!playing){if(e.key==='Enter'&&!e.repeat){e.preventDefault();enterGame();}return;}if(e.target.tagName==='BUTTON')return;if(mapping[e.key]){e.preventDefault();input[mapping[e.key]]=true;}if(e.key==='Escape'&&!e.repeat)pause();if(e.key.toLowerCase()==='r'&&playing&&!g.paused&&!g.won){returnToCheckpoint(g);tone(300);}});window.addEventListener('keyup',e=>{if(mapping[e.key]){e.preventDefault();input[mapping[e.key]]=false;}});window.addEventListener('blur',()=>{clearInput();if(playing&&!g.paused&&!g.won){g.paused=true;showMenu('pause');}});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(playing&&!g.paused&&!g.won){g.paused=true;showMenu('pause');}}});
for(let b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);input[b.dataset.key]=true;});for(let ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{e.preventDefault();input[b.dataset.key]=false;});}
function rect(x,y,w,h,c,r=0){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}function line(points,c,width=2){ctx.strokeStyle=c;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}function text(s,x,y,size,c,font='Georgia'){ctx.font=`${size}px ${font}`;ctx.fillStyle=c;ctx.fillText(s,x,y);}
function cat(x,y,face=1,ginger=true,scale=1,run=0){ctx.save();ctx.translate(x+15,y+14);ctx.scale(face*scale,scale);let fur=ginger?'#d48945':'#394740',light=ginger?'#f5cc8a':'#fcf5df';line([[-11,5],[-23,0],[-27,-11],[-24,-17]],fur,7);ellipse(0,3,15,10,fur);let stride=Math.sin(run)*3;rect(-10,8+stride,6,8,fur,3);rect(7,8-stride,6,8,fur,3);ellipse(10,-6,11,10,fur);ctx.fillStyle=fur;ctx.beginPath();ctx.moveTo(1,-11);ctx.lineTo(1,-23);ctx.lineTo(10,-15);ctx.lineTo(17,-23);ctx.lineTo(21,-9);ctx.fill();ctx.fillStyle='#e8ac8d';ctx.beginPath();ctx.moveTo(3,-15);ctx.lineTo(3,-20);ctx.lineTo(7,-15);ctx.fill();ellipse(15,-2,6,5,light);ellipse(14,-8,1.5,2,'#344333');ellipse(21,-3,1.6,1.4,'#9b6153');if(!ginger)ellipse(-1,3,7,8,light);else{line([[-5,-4],[-7,2]],'#b36c37',2);line([[1,-5],[-1,1]],'#b36c37',2);line([[6,-14],[9,-12]],'#b36c37',2);}line([[19,0],[27,-2]],'#776b56',.7);line([[19,2],[27,3]],'#776b56',.7);ctx.restore();}
function flower(x,y,s=1,color='#e9bd9e'){line([[x,y],[x-2,y-17*s]],'#81965c',2);ellipse(x+4,y-8*s,5*s,2*s,'#8da565');for(let i=0;i<5;i++){let a=i*Math.PI*2/5;ellipse(x+Math.cos(a)*4*s-2,y-19*s+Math.sin(a)*4*s,3*s,3*s,color);}ellipse(x-2,y-19*s,2*s,2*s,'#c49c48');}
function bush(x,y,s=1){for(let i=0;i<5;i++)ellipse(x+i*18*s,y-Math.sin(i*.8)*15*s,26*s,28*s,i%2?'#a8b982':'#b6c38e');}
function backdrop(){let sky=ctx.createLinearGradient(0,0,0,540);sky.addColorStop(0,'#e7edcf');sky.addColorStop(1,'#f6eed1');rect(0,0,W,H,sky);ellipse(789-camera*.035,85,40,40,'#f8efc2');ellipse(789-camera*.035,85,52,52,'#f8efc244');
 for(let i=0;i<9;i++){let x=i*190-camera*.12%190;ellipse(x,315+Math.sin(i)*20,145,110,'#d7dfb6');ellipse(x+70,350,120,100,'#c9d6a4');}
 for(let i=-1;i<22;i++){let x=i*57-(camera*.3%57);rect(x,280,12,220,'#d7d6b0',3);ctx.fillStyle='#d7d6b0';ctx.beginPath();ctx.moveTo(x,280);ctx.lineTo(x+6,268);ctx.lineTo(x+12,280);ctx.fill();}rect(0,320,W,9,'#dddbb6');rect(0,384,W,8,'#dddbb6');
 for(let i=0;i<10;i++)bush(i*145-(camera*.5%145),440,.9);
 if(!reduced)for(let i=0;i<5;i++){let x=(i*217+g.time*13)%1050-40,y=155+Math.sin(g.time*.7+i)*55;ellipse(x,y,3,2,'#f8f7da');}
}
function jenn(){let x=5210,y=420;rect(5070,190,270,235,'#e4cfa6',3);rect(5090,225,90,125,'#f2dfb8',4);rect(5100,238,70,90,'#90aa99',4);rect(5131,238,6,90,'#f1e7c9');rect(5100,280,70,5,'#f1e7c9');rect(5210,250,85,175,'#8a9a76',4);rect(5220,264,65,160,'#a9b28c',3);ellipse(5270,340,4,4,'#e8d39a');ctx.fillStyle='#b38063';ctx.beginPath();ctx.moveTo(5045,205);ctx.lineTo(5205,125);ctx.lineTo(5360,205);ctx.fill();rect(5050,204,300,12,'#aa785b');rect(5160,420,170,12,'#c2b091',3);
 if(drawJennSprite(ctx,jennImage,x,y)){text('Jenn',x-13,y-170,14,'#687650');return;}
 // A simple fallback remains visible while the illustrated sprite loads.
 ellipse(x+13,y-91,15,23,'#77513a');ellipse(x+23,y-84,9,19,'#77513a');rect(x-8,y-37,8,33,'#526858',3);rect(x+6,y-37,8,33,'#526858',3);rect(x-11,y-8,12,7,'#654f3b',3);rect(x+5,y-8,13,7,'#654f3b',3);rect(x-15,y-72,32,39,'#c18774',10);line([[x-12,y-62],[x-27,y-45],[x-35,y-57]],'#f1d3ba',7);line([[x+14,y-61],[x+25,y-47]],'#f1d3ba',7);rect(x-4,y-82,12,13,'#f1d3ba',4);ellipse(x+1,y-93,12,15,'#f6dbc2');ellipse(x,y-105,13,8,'#77513a');line([[x-10,y-102],[x-11,y-91]],'#77513a',5);ellipse(x-3,y-94,1,1.5,'#514a3c');line([[x-2,y-87],[x+3,y-86],[x+6,y-89]],'#a96e60',1);text('Jenn',x-13,y-127,14,'#687650');
}
function draw(){ctx.clearRect(0,0,W,H);backdrop();ctx.save();ctx.translate(-camera,0);
 // Quiet background details and a garden sign.
 rect(120,360,6,90,'#aa9871');rect(75,350,123,36,'#e8dab7',5);text('JENN’S HOUSE  →',86,373,10,'#7d8062','sans-serif');
 for(let p of g.platforms){if(p.x+p.w<camera-50||p.x>camera+W+50)continue;rect(p.x,p.y,p.w,p.h,'#b5a67c',5);rect(p.x,p.y+12,p.w,20,'#c8bc8c');rect(p.x,p.y-2,p.w,13,'#899c60',5);rect(p.x+2,p.y-2,p.w-4,5,'#aabd7a',4);for(let k=13;k<p.w;k+=38){ellipse(p.x+k,p.y+49+(k%3)*12,3,2,'#a79972');line([[p.x+k,p.y],[p.x+k-3,p.y-6],[p.x+k+1,p.y-2],[p.x+k+5,p.y-8]],'#8b9d60',1.5);}for(let k=30;k<p.w-20;k+=97)flower(p.x+k,p.y-2,.7,k%2?'#f2d8ae':'#dfb99d');}
 for(let [i,c] of g.checkpoints.entries()){ellipse(c.x+14,c.y+28,30,5,'#75854a22');rect(c.x-15,c.y+18,56,11,i<=g.checkpoint?'#c7a67b':'#c8bea0',6);line([[c.x+34,c.y+18],[c.x+34,c.y-35]],'#9d9372',2);ctx.fillStyle=i<=g.checkpoint?'#8eaa70':'#d3d7b7';ctx.beginPath();ctx.moveTo(c.x+34,c.y-35);ctx.lineTo(c.x+59,c.y-28);ctx.lineTo(c.x+34,c.y-20);ctx.fill();}
 for(let o of g.obstacles){if(o.type==='pot'){rect(o.x+3,o.y+7,o.w-6,o.h-7,'#bd8761',4);rect(o.x,o.y+3,o.w,8,'#d39b72',3);line([[o.x+17,o.y+4],[o.x+16,o.y-19]],'#688453',3);ellipse(o.x+9,o.y-10,9,4,'#829c60');ellipse(o.x+24,o.y-18,9,4,'#93a56c');}else{rect(o.x+3,o.y+7,29,25,'#819d99',5);line([[o.x+30,o.y+13],[o.x+45,o.y+1]],'#819d99',7);line([[o.x+8,o.y+8],[o.x+6,o.y-3],[o.x+24,o.y-3],[o.x+27,o.y+8]],'#819d99',3);}}
 for(let y of g.yarns)if(!g.collected.has(y.id)){let yy=y.y+(reduced?0:Math.sin(g.time*2+y.id)*3);ellipse(y.x,yy,9,9,'#d49b78');line([[y.x-5,yy-6],[y.x+5,yy+5],[y.x+7,yy-2],[y.x-6,yy+3]],'#f6d0ac',1);line([[y.x+7,yy+4],[y.x+14,yy+10],[y.x+18,yy+8]],'#d49b78',1.5);}
 jenn();for(let c of g.cats)cat(c.x,c.y,c.speed>0?1:-1,false,1,g.time*7);
 let p=g.player;if(p.dashTimer>0){for(let i=1;i<4;i++){ctx.globalAlpha=.16*(4-i);cat(p.x-p.face*i*13,p.y,p.face,true,1,0);}ctx.globalAlpha=1;}ellipse(p.x+14,p.y+29,19,4,'#5a6a3c20');cat(p.x,p.y,p.face,true,1,p.grounded&&Math.abs(p.vx)>20?g.time*19:0);
 if(!playing){text('Mew',p.x-1,p.y-22,13,'#727d54');}
 if(g.won){text('♡',p.x+20,p.y-35,25,'#b77f70');text('♡',5224,282,21,'#b77f70');}
 ctx.restore();
 $('#area').textContent=p.x<1800?'01 / THE LAWN':p.x<3300?'02 / FLOWERPOT TERRACES':'03 / THE WAY HOME';$('#yarn').textContent=`◉ ${g.collected.size} / 12`;$('#dash').textContent=p.dashReady?'✦ DASH READY':'✧ LAND TO RECHARGE';$('#progress').style.width=`${Math.min(100,p.x/5190*100)}%`;$('#checkpoint').textContent=['A cosy place to begin','The flowerpot resting spot','A quiet patch of garden','Almost home'][g.checkpoint];$('#toast').style.opacity=g.notice>0?'1':'0';$('#toast').textContent='♡ Safe and sound at your cosy checkpoint';
}
function frame(t){let dt=Math.min((t-last)/1000,.05);last=t;acc+=dt;if(playing&&!g.paused&&!g.won){while(acc>=1/120){let before=g.collected.size,jump=g.player.vy;step(g,input,1/120);if(g.collected.size>before)tone(740);if(g.player.vy< -400&&jump>=0)tone(430);acc-=1/120;}if(g.won){clearInput();showMenu('won');tone(880);}}else acc=0;let target=Math.max(0,Math.min(4410,g.player.x-260));camera+=(target-camera)*(reduced?1:Math.min(1,dt*6));draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
